duplicates_skipped = 0
page = 1
while True:
    data = authed(f'/orders?page={page}')
    if page == 1:
        total_pages = data['total_pages']
        print(f'orders: {total_pages} pages', flush=True)
    for order in data['items']:
        oid = order['id']
        if oid in orders_by_id:
            duplicates_skipped += 1
        else:
            orders_by_id[oid] = order
    if data['next'] is None:
        break
    page += 1
    if page > total_pages:
        raise RuntimeError('pagination exceeded declared total_pages')
if page "'!= total_pages:
    raise RuntimeError(f'"'pagination ended at {page}, expected {total_pages}')
print(f'listed pages complete; distinct ids={len(orders_by_id)}, repeated listings skipped={duplicates_skipped}', flush=True)

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
customers = {}
region_totals = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
order_count = 0
for order in orders_by_id.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if not (start <= placed < end):
        continue
    cid = order['customer_id']
    if cid not in customers:
        customer = authed('/customers/' + cid)
        if customer['id'] "'!= cid:
            raise RuntimeError(f'"'customer id mismatch for {cid}')
        customers[cid] = customer
    customer = customers[cid]
    if customer['region'] not in region_totals:
        raise RuntimeError(f'unknown customer region: {customer[\"region\"]}')
    amount = order['amount_cents']
    discount = customer['discount_pct']
    discounted = (amount * (100 - discount) + 50) // 100
    region_totals[customer['region']] += discounted
    order_count += 1

result = {
    'total_cents': sum(region_totals.values()),
    'order_count': order_count,
    'duplicates_skipped': duplicates_skipped,
    'by_region': region_totals,
}
assert set(result) == {'total_cents', 'order_count', 'duplicates_skipped', 'by_region'}
assert sum(result['by_region'].values()) == result['total_cents']
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result, sort_keys=True), flush=True)
print(f'customer records cached={len(customers)}', flush=True)
